122	export function useInfiniteMemos(request: Partial<ListMemosRequest> = {}, options?: { enabled?: boolean }) {
123	  return useInfiniteQuery({
124	    queryKey: memoKeys.list(request),
125	    queryFn: async ({ pageParam }) => {
126	      const response = await memoServiceClient.listMemos(
127	        create(ListMemosRequestSchema, {
128	          ...request,
129	          pageToken: pageParam || "",
130	        } as Record<string, unknown>),
131	      );
132	      return response;
133	    },
134	    initialPageParam: "",
135	    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
136	    staleTime: 1000 * 60,
137	    gcTime: 1000 * 60 * 5,
138	    enabled: options?.enabled ?? true,
139	  });
140	}
